import {createSlice} from '@reduxjs/toolkit'


export const userSlice = createSlice({
    name:'user',
    initialState: {
        users: [],
        test: 'THIS IS WORKING',
        loading: false,
        error: ''
    },
    reducers: {
        findMe: (state, action) => {
            alert('do it')
        }
    }
})
export const actions = userSlice.actions
export default userSlice.reducer
